.modal-1__wrap {
    display: inline-block;
}

.modal-1__wrap input {
    display: none;
}

.modal-1__open-label,
.modal-1__close-label {
    cursor: pointer;
}

.modal-1__open-label {
    color: #4f96f6;
    font-size: .95em;
}

.modal-1__open-label:hover {
    text-decoration: underline;
    cursor: pointer;
    color: #c7511f;
}

.modal-1 {
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: 9999;
    display: none;
}

.modal-1__open-input:checked + label + input + .modal-1 {
    display: block;
    animation: modal-1-animation .6s;
}

.modal-1__content-wrap {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: 80%;
    max-width: 650px;
    background-color: #fefefe;
    z-index: 2;
    border-radius: 5px;
}

.modal-1__close-label {
    background-color: #777;
    color: #fff;
    border: 2px solid #fff;
    border-radius: 20px;
    width: 36px;
    height: 36px;
    line-height: 1.5;
    text-align: center;
    display: table-cell;
    position: fixed;
    top: -15px;
    right: -2%;
    z-index: 99999;
    font-size: 1.4em;
}

.modal-1__content {
    max-height: 50vh;
    overflow-y: auto;
    padding: 39px 45px 40px;
}

.modal-1__background {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, .45);
    z-index: 1;
}

@keyframes modal-1-animation {
    0% {
        opacity: 0;
    }
    100% {
        opacity: 1;
    }
}

@media only screen and (max-width: 520px) {
    .modal-1__open-label {
        max-width: 90%;
        padding: .94em 2.1em .94em 2.6em;
    }

    .modal-1__close-label {
        top: -17px;
        right: -4%;
    }

    .modal-1__content-wrap {
        width: 90vw;
    }

    .modal-1__content {
        padding: 33px 21px 35px;
        max-width: 100%;
    }
}

